"use client";

import { Toast as ToastPrimitive } from "@base-ui/react/toast";
import {
  CircleCheckIcon,
  InfoIcon,
  OctagonXIcon,
  TriangleAlertIcon,
  XIcon,
} from "lucide-react";
import * as React from "react";

import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";
import { cn } from "@/lib/utils";

const toast = ToastPrimitive.createToastManager();

const TOAST_TYPE_ICONS: Record<string, React.ReactNode> = {
  success: <CircleCheckIcon className="size-4" />,
  info: <InfoIcon className="size-4 text-muted-foreground" />,
  warning: <TriangleAlertIcon className="size-4" />,
  error: <OctagonXIcon className="size-4 text-destructive" />,
  loading: <Spinner className="size-4" />,
};

function ToastProvider({
  toastManager = toast,
  ...props
}: ToastPrimitive.Provider.Props) {
  return (
    <ToastPrimitive.Provider
      data-slot="toast-provider"
      toastManager={toastManager}
      {...props}
    />
  );
}

function ToastPortal({ ...props }: ToastPrimitive.Portal.Props) {
  return <ToastPrimitive.Portal data-slot="toast-portal" {...props} />;
}

function ToastViewport({ className, ...props }: ToastPrimitive.Viewport.Props) {
  return (
    <ToastPrimitive.Viewport
      data-slot="toast-viewport"
      className={cn(
        "fixed inset-x-4 bottom-4 z-50 mx-auto flex w-auto max-w-[calc(100%-2rem)] flex-col outline-none sm:inset-x-auto sm:right-4 sm:w-[22.5rem]",
        className
      )}
      {...props}
    />
  );
}

function Toast({
  className,
  swipeDirection = ["down", "right"],
  ...props
}: ToastPrimitive.Root.Props) {
  return (
    <ToastPrimitive.Root
      data-slot="toast"
      swipeDirection={swipeDirection}
      className={cn(
        "[--gap:0.75rem] [--peek:0.75rem] [--scale:calc(max(0,1-(var(--toast-index)*0.1)))] [--shrink:calc(1-var(--scale))] [--height:var(--toast-frontmost-height,var(--toast-height))] [--offset-y:calc(var(--toast-offset-y)*-1+(var(--toast-index)*var(--gap)*-1)+var(--toast-swipe-movement-y))] absolute inset-x-0 bottom-0 z-[calc(1000-var(--toast-index))] h-[var(--height)] w-full origin-bottom px-rounded-md px-border-md [--pixel-size:5px] [--px-border-color:color-mix(in_oklab,var(--foreground)_10%,transparent)] bg-popover text-popover-foreground shadow-lg outline-none select-none [transform:translateX(var(--toast-swipe-movement-x))_translateY(calc(var(--toast-swipe-movement-y)-(var(--toast-index)*var(--peek))-(var(--shrink)*var(--height))))_scale(var(--scale))] [transition:transform_0.5s_cubic-bezier(0.22,1,0.36,1),opacity_0.5s,height_0.15s] after:absolute after:inset-x-0 after:top-full after:h-[calc(var(--gap)+1px)] after:content-[''] focus-visible:outline-2 focus-visible:-outline-offset-1 focus-visible:outline-ring data-ending-style:opacity-0 data-expanded:h-[var(--toast-height)] data-expanded:[transform:translateX(var(--toast-swipe-movement-x))_translateY(var(--offset-y))] data-limited:opacity-0 data-starting-style:[transform:translateY(150%)] data-ending-style:data-[swipe-direction=down]:[transform:translateY(calc(var(--toast-swipe-movement-y)+150%))] data-ending-style:data-[swipe-direction=left]:[transform:translateX(calc(var(--toast-swipe-movement-x)-150%))_translateY(var(--offset-y))] data-ending-style:data-[swipe-direction=right]:[transform:translateX(calc(var(--toast-swipe-movement-x)+150%))_translateY(var(--offset-y))] data-ending-style:data-[swipe-direction=up]:[transform:translateY(calc(var(--toast-swipe-movement-y)-150%))] [&[data-ending-style]:not([data-limited]):not([data-swipe-direction])]:[transform:translateY(150%)]",
        className
      )}
      {...props}
    />
  );
}

function ToastContent({ className, ...props }: ToastPrimitive.Content.Props) {
  return (
    <ToastPrimitive.Content
      data-slot="toast-content"
      className={cn(
        "relative flex h-full items-start gap-3 overflow-hidden p-4 pr-10 transition-opacity duration-[250ms] ease-[cubic-bezier(0.22,1,0.36,1)] data-behind:opacity-0 data-expanded:opacity-100",
        className
      )}
      {...props}
    />
  );
}

function ToastTitle({ className, ...props }: ToastPrimitive.Title.Props) {
  return (
    <ToastPrimitive.Title
      data-slot="toast-title"
      className={cn("font-medium text-sm", className)}
      {...props}
    />
  );
}

function ToastDescription({
  className,
  ...props
}: ToastPrimitive.Description.Props) {
  return (
    <ToastPrimitive.Description
      data-slot="toast-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  );
}

function ToastAction({
  className,
  variant = "outline",
  size = "sm",
  ...props
}: ToastPrimitive.Action.Props &
  Pick<React.ComponentProps<typeof Button>, "variant" | "size">) {
  return (
    <ToastPrimitive.Action
      data-slot="toast-action"
      className={cn("shrink-0 self-center", className)}
      render={<Button size={size} variant={variant} />}
      {...props}
    />
  );
}

function ToastClose({ className, ...props }: ToastPrimitive.Close.Props) {
  return (
    <ToastPrimitive.Close
      data-slot="toast-close"
      className={cn("absolute top-1/2 right-2 -translate-y-1/2", className)}
      render={<Button size="icon-xs" variant="ghost" />}
      {...props}
    >
      <XIcon />
      <span className="sr-only">Dismiss</span>
    </ToastPrimitive.Close>
  );
}

function ToastList() {
  const { toasts } = ToastPrimitive.useToastManager();

  return toasts.map((item) => {
    const icon = item.type ? TOAST_TYPE_ICONS[item.type] : null;

    return (
      <Toast key={item.id} toast={item}>
        <ToastContent>
          {icon && (
            <span
              className="mt-0.5 flex shrink-0 items-center"
              data-slot="toast-icon"
            >
              {icon}
            </span>
          )}
          <div className="flex min-w-0 flex-1 flex-col gap-1">
            <ToastTitle />
            <ToastDescription />
          </div>
          <ToastAction />
          <ToastClose />
        </ToastContent>
      </Toast>
    );
  });
}

function Toaster({ ...props }: ToastPrimitive.Provider.Props) {
  return (
    <ToastProvider {...props}>
      <ToastPortal>
        <ToastViewport>
          <ToastList />
        </ToastViewport>
      </ToastPortal>
    </ToastProvider>
  );
}

const { useToastManager } = ToastPrimitive;

export {
  Toast,
  ToastAction,
  ToastClose,
  ToastContent,
  ToastDescription,
  Toaster,
  ToastPortal,
  ToastProvider,
  ToastTitle,
  ToastViewport,
  toast,
  useToastManager,
};

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "group/button px-rounded-md [--pixel-size:4px] inline-flex shrink-0 items-center justify-center text-sm font-medium whitespace-nowrap transition-all outline-none select-none px-ring active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default:
          "px-border-md [--px-border-offset:2px] [--px-face-offset:2px] [--px-border-color:transparent] [--px-bg:var(--primary)] text-primary-foreground hover:[--px-bg:color-mix(in_oklab,var(--primary)_80%,transparent)] dark:focus-visible:[--px-border-color:var(--ring)] dark:focus-visible:[--px-ring-color:transparent]",
        outline:
          "px-border-md [--px-border-offset:2px] [--px-face-offset:2px] [--px-border-color:var(--border)]! [--px-bg:var(--background)] hover:[--px-bg:var(--border)] hover:text-foreground aria-expanded:[--px-bg:var(--border)] aria-expanded:text-foreground dark:[--px-border-color:var(--input)]! dark:[--px-bg:color-mix(in_oklab,var(--input)_30%,transparent)] dark:hover:[--px-bg:var(--input)] dark:focus-visible:[--px-border-color:var(--ring)] dark:focus-visible:[--px-ring-color:transparent]",
        secondary:
          "px-border-md [--px-border-offset:2px] [--px-face-offset:2px] [--px-border-color:transparent] [--px-bg:var(--secondary)] text-secondary-foreground hover:[--px-bg:color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:[--px-bg:var(--secondary)] aria-expanded:text-secondary-foreground dark:focus-visible:[--px-border-color:var(--ring)] dark:focus-visible:[--px-ring-color:transparent]",
        ghost:
          "px-border-md [--px-border-offset:2px] [--px-face-offset:2px] [--px-border-color:transparent] [--px-bg:var(--background)] hover:[--px-bg:var(--border)] hover:text-foreground aria-expanded:[--px-bg:var(--border)] aria-expanded:text-foreground dark:[--px-bg:color-mix(in_oklab,var(--input)_30%,transparent)] dark:hover:[--px-bg:var(--input)] dark:focus-visible:[--px-border-color:var(--ring)] dark:focus-visible:[--px-ring-color:transparent]",
        destructive:
          "px-border-md [--px-border-offset:2px] [--px-face-offset:2px] [--px-border-color:transparent] [--px-bg:color-mix(in_oklab,var(--destructive)_10%,transparent)] text-destructive hover:[--px-bg:color-mix(in_oklab,var(--destructive)_20%,transparent)] focus-visible:[--px-border-color:color-mix(in_oklab,var(--destructive)_40%,transparent)] focus-visible:[--px-ring-color:transparent] dark:[--px-bg:color-mix(in_oklab,var(--destructive)_20%,transparent)] dark:hover:[--px-bg:color-mix(in_oklab,var(--destructive)_30%,transparent)]",
      },
      size: {
        default: "h-9 gap-1.5 px-4 in-data-[slot=button-group]:rounded-md",
        xs: "h-6 gap-1 [--pixel-size:2px] px-2 text-xs in-data-[slot=button-group]:rounded-md [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1 rounded-[min(var(--radius-md),10px)] px-2.5 in-data-[slot=button-group]:rounded-md has-data-[icon]:px-3",
        lg: "h-10 gap-1.5 px-2.5",
        icon: "size-9 [--px-border-color:transparent]",
        "icon-xs":
          "size-6 [--pixel-size:2px] [--px-border-color:transparent] in-data-[slot=button-group]:rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-8 [--px-border-color:transparent] rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-md",
        "icon-lg": "size-10 [--px-border-color:transparent]",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

function Button({
  className,
  variant = "default",
  size = "default",
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      data-variant={variant}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { cn } from "@/lib/utils";

type SpinnerCell =
  | { id: string; kind: "empty" }
  | { id: string; kind: "ring"; delay: string };

// Row-major layout for a 5x5 grid: the 4 corners are cut to approximate a
// circle and the center is left empty, so only the 12 perimeter pixels form
// a hollow ring. Each one fades out over a trailing tail (see
// animate-pixel-spin-dot), and the negative animation-delay staggers them so
// the lit pixels read as one line sweeping counter-clockwise around the ring.
const SPINNER_CELLS: SpinnerCell[] = [
  { id: "r0c0", kind: "empty" },
  { id: "r0c1", kind: "ring", delay: "-825ms" },
  { id: "r0c2", kind: "ring", delay: "-750ms" },
  { id: "r0c3", kind: "ring", delay: "-675ms" },
  { id: "r0c4", kind: "empty" },
  { id: "r1c0", kind: "ring", delay: "0ms" },
  { id: "r1c1", kind: "empty" },
  { id: "r1c2", kind: "empty" },
  { id: "r1c3", kind: "empty" },
  { id: "r1c4", kind: "ring", delay: "-600ms" },
  { id: "r2c0", kind: "ring", delay: "-75ms" },
  { id: "r2c1", kind: "empty" },
  { id: "r2c2", kind: "empty" },
  { id: "r2c3", kind: "empty" },
  { id: "r2c4", kind: "ring", delay: "-525ms" },
  { id: "r3c0", kind: "ring", delay: "-150ms" },
  { id: "r3c1", kind: "empty" },
  { id: "r3c2", kind: "empty" },
  { id: "r3c3", kind: "empty" },
  { id: "r3c4", kind: "ring", delay: "-450ms" },
  { id: "r4c0", kind: "empty" },
  { id: "r4c1", kind: "ring", delay: "-225ms" },
  { id: "r4c2", kind: "ring", delay: "-300ms" },
  { id: "r4c3", kind: "ring", delay: "-375ms" },
  { id: "r4c4", kind: "empty" },
];

function Spinner({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="spinner"
      role="status"
      aria-label="Loading"
      className={cn("grid size-5 grid-cols-5 grid-rows-5", className)}
      {...props}
    >
      {SPINNER_CELLS.map((cell) =>
        cell.kind === "empty" ? (
          <span aria-hidden="true" key={cell.id} />
        ) : (
          <span
            className="animate-pixel-spin-dot bg-foreground"
            key={cell.id}
            style={{ animationDelay: cell.delay }}
          />
        )
      )}
    </span>
  );
}

export { Spinner };
